    string line; // строка, считываемая из файла
    ifstream inputFile("input_file.txt"); // открытый файл для чтения

    if (!inputFile) { // проверяем, открыт ли файл
        cerr << "Error: cannot open input file." << endl;
        return 1;
    }

    while (getline(inputFile, line)) { // считываем файл построчно
        size_t pos = 0;
        while ((pos = line.find(word, pos)) != string::npos) { // находим все вхождения слова в строке
            pos++; // пропускаем найденное слово, чтобы не учитывать повторы в одной строке
            wordCount[word]++; // увеличиваем счетчик вхождений слова
        }
    }

    inputFile.close(); // закрываем файл

    cout << "Word '" << word << "' appears " << wordCount[word] << " times in the file." << endl;

    return 0;
}
``` 

